 const filtered=useMemo(()=>{let rows=stationData.filter(s=>(!query||[s.name,s.address,s.city].join(' ').toLowerCase().includes(query.toLowerCase()))&&(city==='All cities'||s.city===city)&&(connector==='All connectors'||s.connectors.includes(connector))&&(stationType==='All'||s.type===stationType)&&(!availableOnly||s.available>0));if(sort==='Lowest price')rows.sort((a,b)=>a.price-b.price);if(sort==='Fastest')rows.sort((a,b)=>b.power-a.power);if(sort==='Top rated')rows.sort((a,b)=>b.rating-a.rating);return rows},[stationData,query,city,connector,stationType,availableOnly,sort]);
 const current=stationData.find(s=>s.id===selected)||stationData[0];const toggleFav=(id:number)=>setFavs(ids=>ids.includes(id)?ids.filter(i=>i!==id):[...ids,id]);
 const reserve=(s:Station)=>{setSelected(s.id);setBookDate('2026-10-15');setBookTime('10:00');go('Book Station')};
