 const saveCharger=(e:FormEvent)=>{e.preventDefault();if(!hostName.trim()||!hostAddress.trim()||+hostPower<=0||+hostPrice<0){notify('Complete the charger details');return}const id=Math.max(...stationData.map(s=>s.id))+1;setStationData(s=>[{id,name:hostName,city:hostCity,address:hostAddress,type:role==='business'?'B2P':'P2P',power:+hostPower,price:+hostPrice,connectors:[hostConnector],available:1,total:1,rating:5,lat:31.52,lng:74.35,amenities:['Parking'],host:editProfile,hours:hostHours},...s]);setHostActive(a=>[...a,id]);setHostStep(1);setHostName('');setHostAddress('');go(role==='business'?'Stations':'My Chargers');notify('Charger listing added')};
 const displayedBookings=bookings.filter(b=>role==='driver'||role==='admin'||stationData.find(s=>s.id===b.stationId)?.type===(role==='business'?'B2P':'P2P'));
